@php $m0 = now('Asia/Dhaka')->startOfMonth()->toDateString();
$cats = DB::table('account_entries as e')->leftJoin('expense_purposes as p','p.id','=','e.purpose_id')->where('e.entry_date','>=',$m0)->where('e.direction','expense')->select(DB::raw("coalesce(p.name,'No purpose') n"), DB::raw('sum(e.amount) v'), DB::raw('bool_or(coalesce(p.is_expense,true)) x'))->groupBy('n')->orderByDesc('v')->limit(10)->get(); $mx = max(1, (float)($cats->max('v') ?? 1));
$months = DB::table('account_entries')->where('entry_date','>=',now('Asia/Dhaka')->subMonths(5)->startOfMonth()->toDateString())->select(DB::raw("to_char(entry_date,'YYYY-MM') m"), DB::raw("sum(case when direction='income' then amount else 0 end) i"), DB::raw("sum(case when direction='expense' then amount else 0 end) e"))->groupBy('m')->orderBy('m')->get();
$bills = DB::table('bill_statements')->where('status','unpaid')->orderBy('bill_date')->limit(6)->get(); @endphp
